 "content": "from collections import deque


def transform(grid):
    """Reverse the nesting-color order independently in each nonzero object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] != 0):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)

    for comp in components:
        colors = {grid[r][c] for r, c in comp}
        boxes = {}
        for color in colors:
            cells = [(r, c) for r, c in comp if grid[r][c] == color]
            boxes[color] = (min(r for r, _ in cells), max(r for r, _ in cells),
                            min(c for _, c in cells), max(c for _, c in cells))
        # The nested regions are ordered from the largest enclosing box inward.
        order = sorted(colors, key=lambda color: -(
            (boxes[color][1] - boxes[color][0] + 1) *
            (boxes[color][3] - boxes[color][2] + 1)))
        mapping = dict(zip(order, reversed(order)))
        for r, c in comp:
            out[r][c] = mapping[grid[r][c]]
    return out
